INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '成品对应', 'kp-xingce-judgement-analogy-corresponding-product', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "成品对应"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "从原材料到最终产品的加工关系。区分物理变化和化学变化。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、致命考点（物理 vs 化学）"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "物理变化：“木材 : 桌子”。木材还是木头，本质没变。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "化学变化：“葡萄 : 葡萄酒”。发酵了，本质发生了变化。"}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "如果题干是化学变化，选项 A 是物理变化，选项 B 是化学变化，无脑选 B！这是公考类比推理中最硬核的必考点！"}]}]}$$ AS jsonb), NULL, '成品对应的核心考点与解题技巧。', category_node.id, CAST('["判断推理", "成品对应"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_judgement_analogy_corresponding_product", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
